oxy_webhelp_navlinks = {"setup_protection_gws-d39536e44129":{"topics":[{"title":"SLA Domain assignment hierarchy for Google Workspace","shortdesc":"<p class=\"shortdesc\">         <span class=\"ph\">RSC<\/span> provides hierarchy-based, automatic protection for Google Drive and         Gmail workloads to simplify protection across organizations, Organizational Units (OUs), and         individual items.<\/p>","href":"gws\/sla_assignment_hierarchy_gws.html","attributes":{"data-id":"sla_assignment_hierarchy_gws"},"menu":{"hasChildren":false},"tocID":"sla_assignment_hierarchy_gws-d39536e44140","topics":[]},{"title":"SLA Domain options for Google Workspace","shortdesc":"<p class=\"shortdesc\">Understanding the various protection options is important when creating an SLA Domain         for your Google Workspace workloads. This ensures alignment with organizational         needs.<\/p>","href":"gws\/sla_options_gws.html","attributes":{"data-id":"sla_options_gws"},"menu":{"hasChildren":false},"tocID":"sla_options_gws-d39536e44154","topics":[]},{"title":"Group-based protection","shortdesc":"<p class=\"shortdesc\">Group-based protection applies an SLA Domain to the Google Drive and Gmail data of         the members of the groups that you add.<\/p>","href":"gws\/gws_group_based_protection.html","attributes":{"data-id":"gws_group_based_protection"},"menu":{"hasChildren":false},"tocID":"gws_group_based_protection-d39536e44165","next":"gws_group_based_protection-d39536e44165"},{"title":"Google groups protection","shortdesc":"<p class=\"shortdesc\">Google groups protection backs up the Google groups of your Google Workspace         organization, including the settings, aliases, and members of each group, so that you can         restore a group that was deleted or changed.<\/p>","href":"gws\/gws_google_groups_protection.html","attributes":{"data-id":"gws_google_groups_protection"},"menu":{"hasChildren":false},"tocID":"gws_google_groups_protection-d39536e44218","next":"gws_google_groups_protection-d39536e44218"},{"title":"Configure protection for Google Workspace","shortdesc":"<p class=\"shortdesc\">You can create a custom SLA Domain and assign it to your Google Workspace workloads         to begin the protection setup.<\/p>","href":"gws\/configure_protection_gws.html","attributes":{"data-id":"configure_protection_gws"},"menu":{"hasChildren":false},"tocID":"configure_protection_gws-d39536e44240","next":"configure_protection_gws-d39536e44240"}]}};